      throw new Error(`Unknown action ${JSON.stringify(action)}.`);
    }
  };

  return {
    run,
    check: async (js) => {
      await evaluate(options.fill(js));
    },
    // What a person would see, for a failure report.
    snapshot: async () => snapshotPage(),
    render: async (state) => options.render(state),
  };
};

