// A press combo ("Meta+p", "Shift+Enter", "Escape") as the CDP key events
// Input.dispatchKeyEvent takes. Trusted events, so Obsidian's keymap scopes see them.

export type KeyEvent = {
  type: "keyDown" | "keyUp" | "rawKeyDown";
  key: string;
  code: string;
  windowsVirtualKeyCode: number;
  nativeVirtualKeyCode: number;
  modifiers: number;
  text?: string;
};

const MODIFIER_BITS: Record<string, number> = { Alt: 1, Control: 2, Meta: 4, Shift: 8 };
const MODIFIER_ALIASES: Record<string, string> = { Ctrl: "Control", Cmd: "Meta", Command: "Meta", Option: "Alt" };

const NAMED: Record<string, { code: string; keyCode: number }> = {
  Enter: { code: "Enter", keyCode: 13 },
  Escape: { code: "Escape", keyCode: 27 },
  Tab: { code: "Tab", keyCode: 9 },
  Backspace: { code: "Backspace", keyCode: 8 },
  Delete: { code: "Delete", keyCode: 46 },
  Space: { code: "Space", keyCode: 32 },
  ArrowUp: { code: "ArrowUp", keyCode: 38 },
  ArrowDown: { code: "ArrowDown", keyCode: 40 },
  ArrowLeft: { code: "ArrowLeft", keyCode: 37 },
  ArrowRight: { code: "ArrowRight", keyCode: 39 },
  Home: { code: "Home", keyCode: 36 },
  End: { code: "End", keyCode: 35 },
  PageUp: { code: "PageUp", keyCode: 33 },
  PageDown: { code: "PageDown", keyCode: 34 },
  Control: { code: "ControlLeft", keyCode: 17 },
  Shift: { code: "ShiftLeft", keyCode: 16 },
  Alt: { code: "AltLeft", keyCode: 18 },
  Meta: { code: "MetaLeft", keyCode: 91 },
};

const keyOf = (name: string): { key: string; code: string; keyCode: number } => {
  if (name === " ") return { key: " ", ...NAMED.Space };
  const named = NAMED[name];
  if (named) return { key: name, ...named };
  if (/^F([1-9]|1[0-2])$/.test(name)) return { key: name, code: name, keyCode: 111 + Number(name.slice(1)) };
  if (name.length !== 1) throw new Error(`Unknown key "${name}" in a press combo.`);
  const upper = name.toUpperCase();
  if (/[A-Z]/.test(upper)) return { key: name, code: `Key${upper}`, keyCode: upper.charCodeAt(0) };
  if (/[0-9]/.test(name)) return { key: name, code: `Digit${name}`, keyCode: name.charCodeAt(0) };
  return { key: name, code: "", keyCode: name.charCodeAt(0) };
};

// "Meta+Shift+p" -> down/up events. A printable key with no Control/Meta/Alt
// carries text, so it types; with one of them it's a shortcut and doesn't.
export const comboEvents = (combo: string): KeyEvent[] => {
  // "+" alone, or a trailing "++", is the plus key itself.
  const parts = combo === "+" ? ["+"] : combo.endsWith("++") ? [...combo.slice(0, -2).split("+"), "+"] : combo.split("+");
  const names = parts.map((part) => MODIFIER_ALIASES[part] ?? part).filter(Boolean);
  if (!names.length) throw new Error(`Empty press combo "${combo}".`);
  const main = names[names.length - 1];
  const held = names.slice(0, -1);
  for (const name of held) {
    if (!(name in MODIFIER_BITS)) throw new Error(`"${name}" in "${combo}" is not a modifier (Control, Meta, Alt, Shift).`);
  }
  const modifiers = held.reduce((bits, name) => bits | MODIFIER_BITS[name], 0);
  const target = keyOf(main);
  const shortcut = (modifiers & (MODIFIER_BITS.Alt | MODIFIER_BITS.Control | MODIFIER_BITS.Meta)) !== 0;
  const text = !shortcut && target.key.length === 1 ? target.key : target.key === "Enter" && !shortcut ? "\r" : undefined;
  const event = (type: KeyEvent["type"], key: { key: string; code: string; keyCode: number }, bits: number, withText?: string): KeyEvent => ({
    type,
    key: key.key,
    code: key.code,
    windowsVirtualKeyCode: key.keyCode,
    nativeVirtualKeyCode: key.keyCode,
    modifiers: bits,
    ...(withText ? { text: withText } : {}),
  });
  const events: KeyEvent[] = [];
  let bits = 0;
  for (const name of held) {
    bits |= MODIFIER_BITS[name];
    events.push(event("rawKeyDown", keyOf(name), bits));
  }
  events.push(event(text ? "keyDown" : "rawKeyDown", target, modifiers, text));
  events.push(event("keyUp", target, modifiers));
  for (const name of [...held].reverse()) {
    bits &= ~MODIFIER_BITS[name];
    events.push(event("keyUp", keyOf(name), bits));
  }
  return events;
};

// Which Obsidian command a kit's command_palette label means. Obsidian names a
// plugin command "<Plugin name>: <command name>", and kits write the part a user types.

export type PaletteCommand = { id: string; name: string };

const plain = (text: string): string => text.replace(/\s+/g, " ").trim().toLowerCase();

// Exact full name, then exact command part, then the only command whose name
// contains the label. Null when nothing or more than one command matches.
export const pickCommand = (
  label: string,
  commands: PaletteCommand[],
): { command: PaletteCommand | null; candidates: PaletteCommand[] } => {
  const wanted = plain(label);
  const exact = commands.find((command) => plain(command.name) === wanted);
  if (exact) return { command: exact, candidates: [exact] };
  const byPart = commands.filter((command) => plain(command.name.split(": ").slice(1).join(": ")) === wanted);
  if (byPart.length === 1) return { command: byPart[0], candidates: byPart };
  const containing = commands.filter((command) => plain(command.name).includes(wanted));
  if (containing.length === 1) return { command: containing[0], candidates: containing };
  return { command: null, candidates: byPart.length ? byPart : containing };
};

