    }
    if (this.handlers.ours(event)) return;
    if (event instanceof KeyboardEvent && MODIFIERS.has(event.key)) return;
    if (!this.holding) {
      if (event.type === "mousedown" || event.type === "keydown" || event.type === "touchstart") this.touches += 1;
