// The page half of an Obsidian run, bundled and injected over CDP: Sid's
// caption bar and stage, plus the probes the Node executor asks before it acts.
// Buttons reach Node through the __proofCmd binding; nothing here drives the page.
import { CaptionBar, type BarAction, type BarModel } from "../src/roam/bar";
import { Stage } from "../src/roam/stage";
import { center, hitTarget } from "../src/roam/input";
import { isVisible, query } from "../src/roam/selector";

type Probe =
  | { ok: true; x: number; y: number }
  | { ok: false; reason: string };

declare global {
  interface Window {
    __proofCmd?: (payload: string) => void;
    __proofHud?: ReturnType<typeof install>;
  }
}

const SNAPSHOT_LIMIT = 4000;
const LAYERS = ".modal-container .modal, .prompt, .menu, .notice, .suggestion-container";

const describeElement = (element: Element): string => {
  const classes = (element.getAttribute("class") ?? "").trim().split(/\s+/).slice(0, 3).join(".");
  return `<${element.tagName.toLowerCase()}${classes ? `.${classes}` : ""}>`;
};

const send = (action: BarAction): null => {
  window.__proofCmd?.(JSON.stringify(action));
  return null;
};

const isLive = (model: BarModel | null): boolean =>
  Boolean(model && !["done", "stopped"].includes(model.state.phase));

const install = () => {
  const bar = new CaptionBar((action) => {
    // Who has the screen changed in the bar alone; the rest is Node's.
    if (action.kind === "turn" || action.kind === "closed") {
      sync();
      if (action.kind === "closed") send(action);
      return null;
    }
    if (action.kind === "setting" && action.key === "pointer") {
      stage.setPointer(action.value);
      if (model) model = { ...model, pointer: action.value };
      sync();
    }
    if (action.kind === "run" || action.kind === "rerun") stage.prime();
    return send(action);
  });
  const stage = new Stage({
    held: () => send({ kind: "command", cmd: "pause", args: { why: "page" } }),
    toggle: () => model && send({ kind: "command", cmd: model.state.paused ? "resume" : "pause" }),
    next: () => send({ kind: "command", cmd: "next" }),
    ours: (event) => event.composedPath().includes(bar.host),
  });
  document.body.append(bar.host);
  let model: BarModel | null = null;
  let lastAsk = "";

  // The frame, held input and tab title follow the run, as the Roam panel's syncRun.
  const sync = (): void => {
    const state = model?.state;
    if (!model || !state) {
      bar.update(null);
      stage.setLive(false);
      stage.setDriver("none");
      stage.ring(null);
      stage.setTitle(null);
      return;
    }
    const live = isLive(model);
    bar.update(model);
    const driving = live && !state.paused && !state.pending && state.phase !== "waiting-next";
    const failure = state.pending?.kind === "failure" || state.pending?.kind === "check-failed";
    stage.setPointer(model.pointer);
    stage.setLive(live);
    stage.setHolding(driving);
    stage.setDriver(!live ? "none" : failure && !bar.doingIt ? "held" : driving ? "run" : "you");
    if (!live || (!state.executing && state.phase !== "dwell")) {
      stage.ring(null);
      bar.setDodge(false);
    }
    const failed = state.plan.filter((item) => state.results[item.id] === "fail").length;
    if (live) {
      const where = state.caseIndex < 0 ? "setup" : `${state.caseIndex + 1}/${state.caseCount}`;
      stage.setTitle(driving ? `▶ ${where}` : state.paused ? `❚❚ Paused ${where}` : "● Your turn");
    } else {
      stage.setTitle(state.phase === "stopped" ? "❚❚ Stopped" : failed ? `✗ ${failed} failed` : "✓ Passed");
    }
    const ask = live && state.pending ? `${state.pending.kind}:${state.pending.caseId}` : "";
    if (ask && ask !== lastAsk) stage.chime();
    lastAsk = ask;
  };

  return {
    update(next: BarModel | null): void {
      model = next;
      sync();
    },
    target(selector: string | null, verb = "", leadMs = 0): void {
      const element = selector ? query(selector) : null;
      stage.ring(element, verb, leadMs);
      bar.setDodge(Boolean(element && bar.covers(element.getBoundingClientRect())));
    },
    showError(message: string): void {
      bar.showError(message);
    },
    openResult(): void {
      bar.openResult();
    },
    // The run's own CDP input is trusted: the stage lets it through while it acts.
    passing(on: boolean): void {
      stage.setPassing(on);
    },
    visible(selector: string): boolean {
      const element = query(selector);
      return Boolean(element && isVisible(element));
    },
    // Into view in the window and every scrolling parent, then the point a click
    // lands on if the element is visible, enabled and not covered.
    actionable(selector: string, position?: { x: number; y: number }): Probe {
      const element = query(selector);
      if (!element) return { ok: false, reason: `${selector} is not on the page` };
      if (!isVisible(element)) return { ok: false, reason: `${selector} is attached but hidden` };
      const box = element.getBoundingClientRect();
      if (box.bottom <= 0 || box.right <= 0 || box.top >= innerHeight || box.left >= innerWidth) {
        element.scrollIntoView({ block: "center", inline: "nearest" });
        return { ok: false, reason: "the element is still moving" };
      }
      if ((element as HTMLButtonElement).disabled || element.getAttribute("aria-disabled") === "true") {
        return { ok: false, reason: "the element is disabled" };
      }
      const point = position ? { x: box.left + position.x, y: box.top + position.y } : center(element);
      const { covered } = hitTarget(element, point);
      if (covered) return { ok: false, reason: `${describeElement(covered)} intercepts pointer events` };
      return { ok: true, x: point.x, y: point.y };
    },
    focus(selector: string): boolean {
      const element = query(selector) as HTMLElement | null;
      element?.focus();
      return Boolean(element);
    },
    scrollTo(selector: string): boolean {
      const element = query(selector);
      element?.scrollIntoView({ block: "center", inline: "nearest" });
      return Boolean(element);
    },
    // What a person would see, in plain text: the open note, then modals,
    // menus and notices on top of it.
    snapshot(): string {
      const app = (window as unknown as { app?: { workspace?: { getActiveFile?: () => { path: string } | null } } }).app;
      const file = app?.workspace?.getActiveFile?.();
      const layers = Array.from(document.querySelectorAll(LAYERS)).filter(isVisible);
      const lines = [
        `note: ${file ? file.path : "(no active note)"}`,
        ...layers.map((layer) => `${describeElement(layer)} ${(layer.textContent ?? "").replace(/\s+/g, " ").trim().slice(0, 600)}`),
      ];
      return lines.join("\n").slice(0, SNAPSHOT_LIMIT);
    },
    dispose(): void {
      stage.dispose();
      bar.dispose();
    },
  };
};

// A plugin reload keeps the window: replace the old bar instead of stacking a second one.
window.__proofHud?.dispose();
window.__proofHud = install();

