// A CDP session on one page target that also hears events. The verify harness's
// client answers calls only, and Runtime.bindingCalled is an event.

type Pending = { resolve: (value: Record<string, unknown>) => void; reject: (error: Error) => void };
type Listener = (params: Record<string, unknown>) => void;

export type CdpSession = {
  send(method: string, params?: Record<string, unknown>): Promise<Record<string, unknown>>;
  on(event: string, listener: Listener): void;
  close(): void;
};

export const openSession = async (url: string): Promise<CdpSession> => {
  const socket = new WebSocket(url);
  await new Promise<void>((resolve, reject) => {
    socket.addEventListener("open", () => resolve(), { once: true });
    socket.addEventListener("error", () => reject(new Error(`CDP socket to ${url} failed`)), { once: true });
  });
  let nextId = 0;
  const pending = new Map<number, Pending>();
  const listeners = new Map<string, Listener[]>();
  socket.addEventListener("message", (event) => {
    const message = JSON.parse(String(event.data)) as {
      id?: number;
      method?: string;
      params?: Record<string, unknown>;
      result?: Record<string, unknown>;
      error?: { message: string };
    };
    if (message.id !== undefined) {
      const entry = pending.get(message.id);
      if (!entry) return;
      pending.delete(message.id);
      if (message.error) entry.reject(new Error(message.error.message));
      else entry.resolve(message.result ?? {});
      return;
    }
    for (const listener of listeners.get(message.method ?? "") ?? []) listener(message.params ?? {});
  });
  socket.addEventListener("close", () => {
    for (const entry of pending.values()) entry.reject(new Error("CDP socket closed"));
    pending.clear();
  });
  return {
    send: (method, params = {}) =>
      new Promise((resolve, reject) => {
        const id = ++nextId;
        pending.set(id, { resolve, reject });
        socket.send(JSON.stringify({ id, method, params }));
      }),
    on: (event, listener) => listeners.set(event, [...(listeners.get(event) ?? []), listener]),
    close: () => socket.close(),
  };
};

// Runs page js the way Roam's runner does: indirect eval in global scope, a
// promise awaited, the error kind kept in the message.
export const evaluateIn = async (session: CdpSession, js: string): Promise<unknown> => {
  const result = (await session.send("Runtime.evaluate", {
    expression: `(0, eval)(${JSON.stringify(js)})`,
    awaitPromise: true,
    returnByValue: true,
    userGesture: true,
  })) as { result?: { value?: unknown }; exceptionDetails?: { text?: string; exception?: { description?: string } } };
  if (result.exceptionDetails) {
    const details = result.exceptionDetails;
    throw new Error((details.exception?.description ?? details.text ?? "evaluate failed").split("\n    at ")[0]);
  }
  return result.result?.value;
};

// The Executor for a run against Obsidian over CDP: Roam's page executor's
// actions and Playwright-style waits, with trusted input, real screenshots,
// and commands run by id instead of typed into the palette.
import fs from "node:fs/promises";
import path from "node:path";
import type { Action } from "../src/core/action";
import type { ActionHooks, Executor, MachineState } from "../src/core/machine";
import { evaluateIn, type CdpSession } from "./cdp";
import { comboEvents } from "./keys";
import { pickCommand, type PaletteCommand } from "./palette";

export type CdpExecutorOptions = {
  session: CdpSession;
  timeout: number;
  // Fills {{run}}, {{kit}}, {{ns}} and {{env.X}} in every string of an action.
  fill: <T>(value: T) => T;
  render: (state: MachineState) => Promise<void>;
  // Something a person should know that isn't a failure.
  note: (text: string) => void;
  // How long the ring shows before the step acts.
  lead: () => number;
  screenshotDir: string;
};

const sleep = (ms: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms));
const json = JSON.stringify;

const HELD = new Error("held");
const STOPPED = new Error("stopped");
const POLL_MS = 100;
const BUTTONS = { left: 1, middle: 4, right: 2 } as const;

type Probe = { ok: true; x: number; y: number } | { ok: false; reason: string };

export const makeCdpExecutor = (options: CdpExecutorOptions): Executor & { screenshots: string[] } => {
  const { session, timeout } = options;
  const screenshots: string[] = [];
  const page = (js: string): Promise<unknown> => evaluateIn(session, js);
  const hud = (call: string): Promise<unknown> => page(`window.__proofHud && window.__proofHud.${call}`);

  const waitUntil = async <T>(probe: () => Promise<T | null | false>, what: () => string): Promise<T> => {
    const deadline = Date.now() + timeout;
    for (;;) {
      const value = await probe();
      if (value) return value;
      if (Date.now() > deadline) throw new Error(`Timeout ${timeout}ms exceeded waiting for ${what()}.`);
      await sleep(POLL_MS);
    }
  };

  const visible = (selector: string): Promise<true> =>
    waitUntil(async () => (await hud(`visible(${json(selector)})`)) === true || null, () => selector);

  // Visible, enabled, still and uncovered, as Playwright waits before a click.
  const actionable = async (selector: string, position?: { x: number; y: number }): Promise<{ x: number; y: number }> => {
    let last = "";
    let before: { x: number; y: number } | null = null;
    return waitUntil(
      async () => {
        const probe = (await hud(`actionable(${json(selector)}${position ? `, ${json(position)}` : ""})`)) as Probe | undefined;
        if (!probe) throw new Error("The runner's page half is gone; the page reloaded.");
        if (!probe.ok) {
          last = probe.reason;
          before = null;
          return null;
        }
        const still: boolean = before !== null && before.x === probe.x && before.y === probe.y;
        before = { x: probe.x, y: probe.y };
        if (!still) last = "the element is still moving";
        return still ? { x: probe.x, y: probe.y } : null;
      },
      () => `${selector}: ${last || "not found"}`,
    );
  };

  // Our input is trusted, so the stage lets it through only while we act.
  const acting = async <T>(work: () => Promise<T>): Promise<T> => {
    await hud("passing(true)");
    try {
      return await work();
    } finally {
      await hud("passing(false)").catch(() => undefined);
    }
  };

  const mouse = (type: string, x: number, y: number, extra: Record<string, unknown> = {}) =>
    session.send("Input.dispatchMouseEvent", { type, x, y, pointerType: "mouse", ...extra });

  const clickAt = (point: { x: number; y: number }, button: keyof typeof BUTTONS = "left", count = 1) =>
    acting(async () => {
      await mouse("mouseMoved", point.x, point.y);
      for (let n = 1; n <= count; n += 1) {
        await mouse("mousePressed", point.x, point.y, { button, buttons: BUTTONS[button], clickCount: n });
        await mouse("mouseReleased", point.x, point.y, { button, buttons: 0, clickCount: n });
      }
    });

  const press = (combo: string) =>
    acting(async () => {
      for (const event of comboEvents(combo)) await session.send("Input.dispatchKeyEvent", event);
    });

  const typeText = async (text: string, delayMs: number, hooks?: ActionHooks) => {
    for (const char of text) {
      const outcome = (await hooks?.hold()) ?? "go";
      if (outcome === "interrupted") throw STOPPED;
      await acting(() => (char === "\n" ? pressRaw("Enter") : session.send("Input.insertText", { text: char })));
      if (delayMs > 0) await sleep(delayMs);
    }
  };
  const pressRaw = async (combo: string) => {
    for (const event of comboEvents(combo)) await session.send("Input.dispatchKeyEvent", event);
  };

  const show = async (selector: string | null, verb: string): Promise<void> => {
    await hud(`target(${json(selector)}, ${json(verb)}, ${options.lead()})`);
    if (selector) await sleep(options.lead());
  };

  const gate = async (hooks: ActionHooks | undefined): Promise<void> => {
    const outcome = (await hooks?.hold()) ?? "go";
    if (outcome === "held") throw HELD;
    if (outcome === "interrupted") throw STOPPED;
  };

  // Commands by id: the palette's own UI is a modal a run would have to clean up.
  const runCommand = async (label: string): Promise<void> => {
    const commands = (await page(
      "Object.values(app.commands.commands).map((command) => ({ id: command.id, name: command.name }))",
    )) as PaletteCommand[];
    const { command, candidates } = pickCommand(label, commands);
    if (!command) {
      const names = candidates.slice(0, 5).map((item) => item.name).join("; ");
      throw new Error(
        candidates.length
          ? `"${label}" matches more than one command: ${names}. Use the full name.`
          : `No command palette entry matches "${label}". Is the plugin loaded, and the command's setting on?`,
      );
    }
    const ran = await page(`app.commands.executeCommandById(${json(command.id)})`);
    if (ran === false) throw new Error(`"${command.name}" can't run here (its check failed), e.g. it needs an open note.`);
    await sleep(150);
  };

  const run = async (raw: Action, hooks?: ActionHooks): Promise<void> => {
    for (;;) {
      try {
        return await act(raw, hooks);
      } catch (error) {
        if (error === HELD) continue;
        if (error === STOPPED) return;
        throw error;
      }
    }
  };

  const act = async (raw: Action, hooks?: ActionHooks): Promise<void> => {
    const action = options.fill(raw);
    if ("click" in action) {
      const spec = typeof action.click === "string" ? { selector: action.click } : action.click;
      const point = await actionable(spec.selector, spec.position);
      await show(spec.selector, spec.button === "right" ? "Right-click" : (spec.count ?? 1) > 1 ? "Double-click" : "Click");
      await gate(hooks);
      await clickAt(await actionable(spec.selector, spec.position).catch(() => point), spec.button, spec.count);
    } else if ("type" in action) {
      const point = await actionable(action.type.into);
      await show(action.type.into, "Type");
      await gate(hooks);
      await clickAt(point);
      await typeText(action.type.text, action.type.delay_ms ?? 50, hooks);
    } else if ("fill" in action) {
      const point = await actionable(action.fill.into);
      await show(action.fill.into, "Type");
      await gate(hooks);
      await clickAt(point);
      await press(process.platform === "darwin" ? "Meta+a" : "Control+a");
      await press("Backspace");
      await acting(() => session.send("Input.insertText", { text: action.fill.text }));
    } else if ("press" in action) {
      if (typeof action.press === "string") {
        await gate(hooks);
        await press(action.press);
      } else {
        if (action.press.selector) {
          await actionable(action.press.selector);
          await show(action.press.selector, `Press ${action.press.key}`);
          await gate(hooks);
          await hud(`focus(${json(action.press.selector)})`);
        } else await gate(hooks);
        await press(action.press.key);
      }
    } else if ("hover" in action) {
      await visible(action.hover);
      const point = await actionable(action.hover);
      await show(action.hover, "Hover");
      await gate(hooks);
      await acting(() => mouse("mouseMoved", point.x, point.y));
    } else if ("scroll" in action) {
      if (typeof action.scroll === "number") await acting(() => mouse("mouseWheel", 640, 360, { deltaX: 0, deltaY: action.scroll }));
      else if (action.scroll.to) {
        await visible(action.scroll.to);
        await hud(`scrollTo(${json(action.scroll.to)})`);
      } else await acting(() => mouse("mouseWheel", 640, 360, { deltaX: 0, deltaY: (action.scroll as { y?: number }).y ?? 0 }));
    } else if ("pause" in action) {
      await sleep(action.pause * 1000);
    } else if ("wait_for" in action) {
      await visible(action.wait_for);
    } else if ("open" in action) {
      // In Obsidian a run opens a note by its vault path; there are no URLs to follow.
      await page(`proof.obsidian.open(${json(action.open)})`);
      await sleep(300);
    } else if ("js" in action) {
      await page(action.js);
    } else if ("screenshot" in action) {
      const { data } = (await session.send("Page.captureScreenshot", { format: "png" })) as { data: string };
      await fs.mkdir(options.screenshotDir, { recursive: true });
      const file = path.join(options.screenshotDir, `${action.screenshot}.png`);
      await fs.writeFile(file, Buffer.from(data, "base64"));
      screenshots.push(file);
    } else if ("drag" in action) {
      if (action.drag.hover) {
        const hover = await actionable(action.drag.hover);
        await gate(hooks);
        await acting(() => mouse("mouseMoved", hover.x, hover.y));
      }
      const from = await actionable(action.drag.from);
      await show(action.drag.from, "Drag");
      const to = await actionable(action.drag.to, action.drag.toPosition);
      await gate(hooks);
      // Small moves between press and release, so tldraw and drag-and-drop see a drag.
      await acting(async () => {
        await mouse("mouseMoved", from.x, from.y);
        await mouse("mousePressed", from.x, from.y, { button: "left", buttons: 1, clickCount: 1 });
        for (let n = 1; n <= 10; n += 1) {
          await mouse("mouseMoved", from.x + ((to.x - from.x) * n) / 10, from.y + ((to.y - from.y) * n) / 10, { button: "left", buttons: 1 });
          await sleep(16);
        }
        await mouse("mouseReleased", to.x, to.y, { button: "left", buttons: 0, clickCount: 1 });
      });
    } else if ("command_palette" in action) {
      const value = action.command_palette;
      await gate(hooks);
      await runCommand(typeof value === "string" ? value : value.label);
    } else if ("when" in action) {
      if (await page(action.when.js)) {
        for (const inner of action.when.do) await run(inner, hooks);
      }
    } else {
      throw new Error(`Unknown action ${json(action)}.`);
    }
  };

  return {
    run,
    check: async (js) => {
      await page(options.fill(js));
    },
    // What a person would see, for a failure report, with a screenshot beside it.
    snapshot: async () => {
      const text = String((await hud("snapshot()").catch(() => "")) ?? "");
      const { data } = (await session.send("Page.captureScreenshot", { format: "png" }).catch(() => ({ data: "" }))) as { data: string };
      if (!data) return text;
      await fs.mkdir(options.screenshotDir, { recursive: true });
      const file = path.join(options.screenshotDir, `failure-${Date.now()}.png`);
      await fs.writeFile(file, Buffer.from(data, "base64"));
      screenshots.push(file);
      return `${text}\nscreenshot: ${file}`;
    },
    render: (state) => options.render(state),
    screenshots,
  };
};

