import { describe, expect, it } from "vitest";
import { comboEvents } from "../obsidian/keys";
import { pickCommand } from "../obsidian/palette";

describe("comboEvents", () => {
  it("holds the modifiers around a shortcut and sends no text", () => {
    const events = comboEvents("Meta+p");
    expect(events.map((event) => [event.type, event.key, event.modifiers])).toEqual([
      ["rawKeyDown", "Meta", 4],
      ["rawKeyDown", "p", 4],
      ["keyUp", "p", 4],
      ["keyUp", "Meta", 0],
    ]);
    expect(events.some((event) => event.text)).toBe(false);
  });

  it("types a printable key and Enter, but not Escape", () => {
    expect(comboEvents("a")[0]).toMatchObject({ type: "keyDown", text: "a", code: "KeyA" });
    expect(comboEvents("Shift+Enter")[1]).toMatchObject({ key: "Enter", text: "\r", modifiers: 8 });
    expect(comboEvents("Escape")[0]).toMatchObject({ type: "rawKeyDown", windowsVirtualKeyCode: 27 });
    expect(comboEvents("Escape")[0].text).toBeUndefined();
  });

  it("reads aliases and the plus key", () => {
    expect(comboEvents("Ctrl+Cmd+k")[1]).toMatchObject({ key: "Meta", modifiers: 6 });
    expect(comboEvents("Shift++").at(-2)).toMatchObject({ key: "+" });
  });

  it("rejects what isn't a key", () => {
    expect(() => comboEvents("p+Meta")).toThrow(/not a modifier/);
    expect(() => comboEvents("Hyper")).toThrow(/Unknown key/);
  });
});

describe("pickCommand", () => {
  const commands = [
    { id: "dg:create", name: "Discourse Graph: Create discourse node" },
    { id: "dg:toggle", name: "Discourse Graph: Toggle discourse context" },
    { id: "core:toggle", name: "Toggle left sidebar" },
    { id: "other:create", name: "Other plugin: Create discourse node" },
  ];

  it("takes the full name first", () => {
    expect(pickCommand("Discourse Graph: Create discourse node", commands).command?.id).toBe("dg:create");
  });

  it("takes the command part a user types when only one plugin has it", () => {
    expect(pickCommand("toggle discourse context", commands).command?.id).toBe("dg:toggle");
  });

  it("refuses a label two commands share, and lists them", () => {
    const { command, candidates } = pickCommand("Create discourse node", commands);
    expect(command).toBeNull();
    expect(candidates.map((item) => item.id)).toEqual(["dg:create", "other:create"]);
  });

  it("falls back to the only name containing the label", () => {
    expect(pickCommand("left sidebar", commands).command?.id).toBe("core:toggle");
    expect(pickCommand("nothing like it", commands).command).toBeNull();
  });
});

