          ref={rInput}
          className="tlui-edit-link-dialog__input"
          label="edit-link-dialog.url"
          autoFocus
          autoSelect
          placeholder="https://example.com"
          value={urlInputState.actual}
          onValueChange={handleChange}
          onComplete={handleComplete}
          onCancel={handleCancel}
        />
        <div>
          {!urlInputState.valid
            ? "Invalid URL"
            : acceptsPageLinks(shapeType)
              ? "Enter a URL, or an obsidian:// link to a page."
              : "Enter a URL."}
        </div>
      </div>
    </TldrawUiDialogBody>
    <TldrawUiDialogFooter className="tlui-dialog__footer__actions">
      <TldrawUiButton
        type="normal"
        onClick={handleCancel}
        onTouchEnd={handleCancel}
      >
        <TldrawUiButtonLabel>Cancel</TldrawUiButtonLabel>
      </TldrawUiButton>
      {isRemoving ? (
        <TldrawUiButton
          type="danger"
          onClick={handleClear}
          onTouchEnd={handleClear}
        >
          <TldrawUiButtonLabel>Clear</TldrawUiButtonLabel>
        </TldrawUiButton>
      ) : (
        <TldrawUiButton
          type="primary"
          disabled={!urlInputState.valid}
          onClick={handleComplete}
          onTouchEnd={handleComplete}
        >
          <TldrawUiButtonLabel>Save</TldrawUiButtonLabel>
        </TldrawUiButton>
      )}
    </TldrawUiDialogFooter>

